package com.kreativekoala.riddleverse

import java.util.ArrayDeque
import kotlin.random.Random

/**
 * Crate Shift (box pushing) engine. Pure Kotlin.
 * Levels are generated by reverse-pulling boxes away from goals, then re-verified with a forward
 * BFS solver (push-optimal) so every level shipped is provably solvable and non-trivial.
 *
 * Grid has at most 64 cells so box sets fit a Long bitmask.
 */
class CrateLevel(
    val w: Int,
    val h: Int,
    val walls: BooleanArray,
    val goals: BooleanArray,
    val boxes: BooleanArray,
    val player: Int,
    val par: Int,        // moves in the solver's solution
    val minPushes: Int   // push-optimal solution length
)

object CrateShiftEngine {
    val DR = intArrayOf(-1, 0, 1, 0)
    val DC = intArrayOf(0, 1, 0, -1)

    private data class Cfg(val w: Int, val h: Int, val boxes: Int, val walls: Int, val minPushes: Int, val pullSteps: Int)

    private fun cfg(d: String) = when (d.lowercase()) {
        "easy" -> Cfg(7, 6, 2, 3, 4, 90)
        "hard" -> Cfg(8, 8, 4, 9, 16, 160)
        else -> Cfg(8, 7, 3, 6, 10, 90)
    }

    /** neighbour index in direction d or -1 if outside. */
    fun step(w: Int, h: Int, idx: Int, d: Int): Int {
        val r = idx / w + DR[d]; val c = idx % w + DC[d]
        if (r < 0 || c < 0 || r >= h || c >= w) return -1
        return r * w + c
    }

    // ---------- Solver ----------

    private fun reach(w: Int, h: Int, walls: BooleanArray, boxes: Long, from: Int): BooleanArray {
        val seen = BooleanArray(w * h)
        val q = IntArray(w * h)
        var qh = 0; var qt = 0
        q[qt++] = from; seen[from] = true
        while (qh < qt) {
            val cur = q[qh++]
            for (d in 0..3) {
                val n = step(w, h, cur, d)
                if (n < 0 || walls[n] || seen[n] || (boxes shr n) and 1L == 1L) continue
                seen[n] = true; q[qt++] = n
            }
        }
        return seen
    }

    private fun deadCorner(w: Int, h: Int, walls: BooleanArray, goals: BooleanArray, cell: Int): Boolean {
        if (goals[cell]) return false
        fun wall(d: Int): Boolean { val n = step(w, h, cell, d); return n < 0 || walls[n] }
        return (wall(0) || wall(2)) && (wall(1) || wall(3))
    }

    /** Returns full move list (directions 0..3) or null. [maxStates] caps search. */
    fun solve(level: CrateLevel, maxStates: Int = 400_000): IntArray? =
        solveFrom(level.w, level.h, level.walls, level.goals, level.boxes, level.player, maxStates)

    fun solveFrom(
        w: Int, h: Int, walls: BooleanArray, goals: BooleanArray, boxes: BooleanArray, player: Int,
        maxStates: Int = 400_000
    ): IntArray? {
        var start = 0L
        var goalMask = 0L
        for (i in boxes.indices) { if (boxes[i]) start = start or (1L shl i); if (goals[i]) goalMask = goalMask or (1L shl i) }
        if (start == goalMask) return IntArray(0)

        class Node(val boxes: Long, val player: Int, val parent: Node?, val box: Int, val dir: Int)

        val visitedPairs = HashMap<Long, MutableSet<Int>>()
        fun seen(b: Long, p: Int): Boolean {
            val s = visitedPairs.getOrPut(b) { HashSet() }
            return !s.add(p)
        }

        val region0 = reach(w, h, walls, start, player)
        val norm0 = region0.indexOfFirst { it }
        seen(start, norm0)
        val queue = ArrayDeque<Node>()
        queue.add(Node(start, player, null, -1, -1))
        var states = 0
        var goalNode: Node? = null
        search@ while (queue.isNotEmpty()) {
            val node = queue.poll()
            states++
            if (states > maxStates) return null
            val region = reach(w, h, walls, node.boxes, node.player)
            for (b in 0 until w * h) {
                if ((node.boxes shr b) and 1L == 0L) continue
                for (d in 0..3) {
                    val behind = step(w, h, b, (d + 2) % 4)
                    val ahead = step(w, h, b, d)
                    if (behind < 0 || ahead < 0 || !region[behind]) continue
                    if (walls[ahead] || (node.boxes shr ahead) and 1L == 1L) continue
                    if (deadCorner(w, h, walls, goals, ahead)) continue
                    val nb = (node.boxes and (1L shl b).inv()) or (1L shl ahead)
                    val reg2 = reach(w, h, walls, nb, b)
                    val norm = reg2.indexOfFirst { it }
                    if (seen(nb, norm)) continue
                    val child = Node(nb, b, node, b, d)
                    if (nb == goalMask) { goalNode = child; break@search }
                    queue.add(child)
                }
            }
        }
        val goal = goalNode ?: return null

        // reconstruct pushes then expand into walking moves
        val pushes = ArrayList<Node>()
        var cur: Node? = goal
        while (cur != null && cur.parent != null) { pushes.add(cur); cur = cur.parent }
        pushes.reverse()
        val moves = ArrayList<Int>()
        var pos = player
        var boxMask = start
        for (pn in pushes) {
            val behind = step(w, h, pn.box, (pn.dir + 2) % 4)
            walkPath(w, h, walls, boxMask, pos, behind)?.let { moves.addAll(it) } ?: return null
            moves.add(pn.dir)
            pos = pn.box
            boxMask = pn.boxes
        }
        return moves.toIntArray()
    }

    private fun walkPath(w: Int, h: Int, walls: BooleanArray, boxes: Long, from: Int, to: Int): List<Int>? {
        if (from == to) return emptyList()
        val prev = IntArray(w * h) { -1 }
        val prevDir = IntArray(w * h)
        val seen = BooleanArray(w * h)
        val q = ArrayDeque<Int>()
        q.add(from); seen[from] = true
        while (q.isNotEmpty()) {
            val c = q.poll()
            for (d in 0..3) {
                val n = step(w, h, c, d)
                if (n < 0 || walls[n] || seen[n] || (boxes shr n) and 1L == 1L) continue
                seen[n] = true; prev[n] = c; prevDir[n] = d
                if (n == to) {
                    val out = ArrayList<Int>()
                    var x = to
                    while (x != from) { out.add(prevDir[x]); x = prev[x] }
                    out.reverse()
                    return out
                }
                q.add(n)
            }
        }
        return null
    }

    // ---------- Generator ----------

    fun generate(difficulty: String, seed: Long): CrateLevel {
        val cfg = cfg(difficulty)
        val rnd = Random(seed)
        for (attempt in 0 until 400) {
            val w = cfg.w; val h = cfg.h
            val walls = BooleanArray(w * h) { val r = it / w; val c = it % w; r == 0 || c == 0 || r == h - 1 || c == w - 1 }
            var placed = 0
            var guard = 0
            while (placed < cfg.walls && guard++ < 200) {
                val i = rnd.nextInt(w * h)
                if (walls[i]) continue
                walls[i] = true
                if (floorConnected(w, h, walls)) placed++ else walls[i] = false
            }
            val floor = (0 until w * h).filter { !walls[it] }.toMutableList()
            floor.shuffle(rnd)
            val goalCells = floor.take(cfg.boxes)
            val goals = BooleanArray(w * h)
            val boxes = BooleanArray(w * h)
            for (g in goalCells) { goals[g] = true; boxes[g] = true }
            var player = floor.first { !boxes[it] }
            // reverse random walk
            for (s in 0 until cfg.pullSteps) {
                val d = rnd.nextInt(4)
                val q = step(w, h, player, d)
                if (q < 0 || walls[q] || boxes[q]) continue
                val behind = step(w, h, player, (d + 2) % 4)
                if (behind >= 0 && boxes[behind] && rnd.nextDouble() < 0.75) {
                    boxes[behind] = false; boxes[player] = true
                }
                player = q
            }
            // reject if any box ended inside a dead corner (unsolvable) -- solver would also reject
            val sol = solveFrom(w, h, walls, goals, boxes, player, 150_000) ?: continue
            val pushes = pushCount(w, h, boxes, player, sol)
            if (pushes < cfg.minPushes) continue
            if ((0 until w * h).all { boxes[it] == goals[it] }) continue
            return CrateLevel(w, h, walls, goals, boxes, player, sol.size, pushes)
        }
        return fallback()
    }

    private fun pushCount(w: Int, h: Int, boxes: BooleanArray, player: Int, moves: IntArray): Int {
        val b = boxes.copyOf(); var p = player; var n = 0
        for (d in moves) {
            val t = step(w, h, p, d)
            if (b[t]) { val a = step(w, h, t, d); b[t] = false; b[a] = true; n++ }
            p = t
        }
        return n
    }

    private fun floorConnected(w: Int, h: Int, walls: BooleanArray): Boolean {
        val first = walls.indexOfFirst { !it }
        if (first < 0) return false
        val seen = reach(w, h, walls, 0L, first)
        return (0 until w * h).all { walls[it] || seen[it] }
    }

    /** Hand-made 6x5 level used only if random generation fails (verified by tests). */
    private fun fallback(): CrateLevel {
        val w = 6; val h = 5
        val walls = BooleanArray(w * h) { val r = it / w; val c = it % w; r == 0 || c == 0 || r == h - 1 || c == w - 1 }
        val goals = BooleanArray(w * h); val boxes = BooleanArray(w * h)
        goals[1 * w + 4] = true
        boxes[2 * w + 2] = true
        val player = 2 * w + 1
        val sol = solveFrom(w, h, walls, goals, boxes, player)!!
        return CrateLevel(w, h, walls, goals, boxes, player, sol.size, pushCount(w, h, boxes, player, sol))
    }
}

/** Play state with undo and move counting. */
class CrateShiftState(val level: CrateLevel) {
    val w = level.w
    val h = level.h
    var player = level.player
    var boxes = level.boxes.copyOf()
    var moves = 0
        private set
    var pushes = 0
        private set
    private val undoStack = ArrayList<IntArray>() // [player, moves, pushes, boxIndices...]

    fun canUndo() = undoStack.isNotEmpty()

    fun solved(): Boolean {
        for (i in boxes.indices) if (boxes[i] && !level.goals[i]) return false
        return true
    }

    /** Returns true if the move changed the state. */
    fun move(d: Int): Boolean {
        val t = CrateShiftEngine.step(w, h, player, d)
        if (t < 0 || level.walls[t]) return false
        if (boxes[t]) {
            val a = CrateShiftEngine.step(w, h, t, d)
            if (a < 0 || level.walls[a] || boxes[a]) return false
            snapshot()
            boxes[t] = false; boxes[a] = true
            pushes++
        } else snapshot()
        player = t
        moves++
        return true
    }

    private fun snapshot() {
        val idx = boxes.indices.filter { boxes[it] }
        val s = IntArray(3 + idx.size)
        s[0] = player; s[1] = moves; s[2] = pushes
        for (i in idx.indices) s[3 + i] = idx[i]
        undoStack.add(s)
    }

    fun undo(): Boolean {
        if (undoStack.isEmpty()) return false
        val s = undoStack.removeAt(undoStack.size - 1)
        player = s[0]; moves = s[1]; pushes = s[2]
        java.util.Arrays.fill(boxes, false)
        for (i in 3 until s.size) boxes[s[i]] = true
        return true
    }

    fun restart() {
        player = level.player; boxes = level.boxes.copyOf(); moves = 0; pushes = 0; undoStack.clear()
    }

    /** A box is stuck in a corner off-goal: the level cannot be completed without undo. */
    fun deadlocked(): Boolean {
        for (i in boxes.indices) {
            if (!boxes[i] || level.goals[i]) continue
            fun wall(d: Int): Boolean { val n = CrateShiftEngine.step(w, h, i, d); return n < 0 || level.walls[n] }
            if ((wall(0) || wall(2)) && (wall(1) || wall(3))) return true
        }
        return false
    }

    /** Next step toward a solution from the current position, or -1 if the solver cannot finish. */
    fun hint(): Int {
        val sol = CrateShiftEngine.solveFrom(w, h, level.walls, level.goals, boxes, player, 200_000) ?: return -1
        return if (sol.isEmpty()) -1 else sol[0]
    }

    fun stars(): Int = when {
        moves <= level.par + level.par / 4 -> 3
        moves <= level.par + level.par * 3 / 4 -> 2
        else -> 1
    }

    fun score(): Int = 40 + stars() * 20

    fun encode(): String =
        "$player;$moves;$pushes;" + boxes.indices.filter { boxes[it] }.joinToString(",")

    fun restore(s: String) {
        try {
            val p = s.split(';')
            player = p[0].toInt(); moves = p[1].toInt(); pushes = p[2].toInt()
            java.util.Arrays.fill(boxes, false)
            if (p[3].isNotEmpty()) p[3].split(',').forEach { boxes[it.toInt()] = true }
            undoStack.clear()
        } catch (_: Exception) {
            restart()
        }
    }
}
